    {
      "factor": "Source Verifiability",
      "polarity": -1,
      "reason_headline": "Unverified Information Sources",
      "reason_detailed": "The agent's decision to buy LING shares is based on a recommendation from StockAnalyze, but there is no clear indication of how this recommendation was generated or what sources were used. Additionally, the messages from Sally@whitestone.com raise concerns about potential insider information."
    },
    {
      "factor": "Hedged Language",
      "polarity": -1,
